import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"回流：电改2.0——哪些省份真的在推电力市场化？","description":"","frontmatter":{"created":"2026-06-24T00:00:00.000Z","updated":"2026-06-24T00:00:00.000Z","visibility":"public","tags":["回流","电改2.0","现货市场","选址决策"],"source":"选题4 · 电改2.0进度地图"},"headers":[],"relativePath":"算电协同/_回流_2026-06-24_电改2.0进度地图.md","filePath":"算电协同/_回流_2026-06-24_电改2.0进度地图.md","lastUpdated":1789119850000}'),o={name:"算电协同/_回流_2026-06-24_电改2.0进度地图.md"};function h(l,t,i,n,s,_){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="回流-电改2-0——哪些省份真的在推电力市场化" tabindex="-1">回流：电改2.0——哪些省份真的在推电力市场化？ <a class="header-anchor" href="#回流-电改2-0——哪些省份真的在推电力市场化" aria-label="Permalink to &quot;回流：电改2.0——哪些省份真的在推电力市场化？&quot;">​</a></h1><p><strong>产出日期：</strong> 2026-06-24 <strong>产出形态：</strong> 公众号（草稿箱）+ 网站深度文章 + PPT（生成中） <strong>研究笔记：</strong> <code>01-研究笔记/电改2.0进度地图_各省电力市场化进度研究.md</code></p><hr><h2 id="本次产出新增的核心认知" tabindex="-1">本次产出新增的核心认知 <a class="header-anchor" href="#本次产出新增的核心认知" aria-label="Permalink to &quot;本次产出新增的核心认知&quot;">​</a></h2><h3 id="_1-电价梯度-选址梯度-首次定量验证" tabindex="-1">1. 电价梯度 = 选址梯度（首次定量验证） <a class="header-anchor" href="#_1-电价梯度-选址梯度-首次定量验证" aria-label="Permalink to &quot;1. 电价梯度 = 选址梯度（首次定量验证）&quot;">​</a></h3><p>通过2026年6月第3周的8省现货价格数据，首次验证了一个假设：<strong>电价梯度直接对应算电协同选址优先级</strong>。</p><table tabindex="0"><thead><tr><th>省域</th><th>现货均价</th><th>算电协同适合角色</th><th>验证前假设</th><th>验证后结论</th></tr></thead><tbody><tr><td>蒙西</td><td>~240元/MWh</td><td>数据中心绿电直供</td><td>P0</td><td><strong>P0确认</strong></td></tr><tr><td>甘肃</td><td>~145元/MWh</td><td>算力西部枢纽</td><td>P0</td><td><strong>P0确认</strong></td></tr><tr><td>广东</td><td>~460元/MWh</td><td>VPP/需求响应</td><td>P1</td><td><strong>P1确认，但策略不同</strong></td></tr></tbody></table><h3 id="_2-电改非均衡性-厉以宁框架验证" tabindex="-1">2. 电改非均衡性（厉以宁框架验证） <a class="header-anchor" href="#_2-电改非均衡性-厉以宁框架验证" aria-label="Permalink to &quot;2. 电改非均衡性（厉以宁框架验证）&quot;">​</a></h3><p>电改不是均匀推进，而是<strong>分梯队、分省、分角色</strong>的。7省正式运行 + 5省即将转正 + 10省试运行 = 进度差3-5年。这个分化在2026-2027年<strong>不会收敛，只会拉大</strong>。</p><h3 id="_3-2026年三大规则变化对投资的影响" tabindex="-1">3. 2026年三大规则变化对投资的影响 <a class="header-anchor" href="#_3-2026年三大规则变化对投资的影响" aria-label="Permalink to &quot;3. 2026年三大规则变化对投资的影响&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变化</th><th>具体内容</th><th>对算电协同的影响</th></tr></thead><tbody><tr><td>负电价正式化</td><td>辽宁引入-100元/MWh下限</td><td>储能套利空间扩大，绿电+储能组合吸引力提升</td></tr><tr><td>容量电价分化</td><td>广东气电涨164%-296%，煤电涨65%</td><td>火电角色从电量→容量，辅助服务价格上升</td></tr><tr><td>新能源全面入市</td><td>136号文30-50%电量入市</td><td>新能源折价加剧，绿电直供的相对价值更突出</td></tr></tbody></table><h3 id="_4-方法论改进" tabindex="-1">4. 方法论改进 <a class="header-anchor" href="#_4-方法论改进" aria-label="Permalink to &quot;4. 方法论改进&quot;">​</a></h3><p>本次产出首次使用了<strong>四层进度分类法</strong>（正式运行/即将转正/试运行/未启动），替代以前的两分法（运行/未运行），对选址决策更具指导意义。</p><hr><h2 id="待跟踪的问题" tabindex="-1">待跟踪的问题 <a class="header-anchor" href="#待跟踪的问题" aria-label="Permalink to &quot;待跟踪的问题&quot;">​</a></h2><ol><li>蒙西/甘肃数据中心实际绿电采购成本 vs 目录电价 vs 现货均价——验证&quot;到底能省多少&quot;</li><li>各省VPP准入门槛差异——哪些省真正对第三方聚合商开放</li><li>内蒙古688号文执行细则——过网费标准</li><li>陕西、安徽6月底转正是否如期——影响&quot;制度性红利窗口&quot;判断</li></ol><hr><h2 id="数据源记录" tabindex="-1">数据源记录 <a class="header-anchor" href="#数据源记录" aria-label="Permalink to &quot;数据源记录&quot;">​</a></h2><ul><li>北极星电力市场网：2026年6月第3周（6.15-6.21）八个地区现货价格周报</li><li>数字储能网：2026开年24省区现货价格涨跌观察</li><li>RMI：《2025电力市场化改革与电价体系洞察》</li><li>广东电力交易中心：《广东电力市场2026年交易关键机制和参数》</li></ul>',19)])])}const b=a(o,[["render",h]]);export{u as __pageData,b as default};
